def encode_bpe(text, merges):
    \

    tokens = list(text)

    for merge_pair_item in merges:
        i = 0
        while i < len(tokens) - 1:
            if (tokens[i], tokens[i + 1]) == merge_pair_item:
                tokens[i] = tokens[i] + tokens[i + 1]
                del tokens[i + 1]
            else:
                i += 1

    return tokens


